UPDATE email_threads t SET has_received_mail = calc.received FROM (SELECT EXISTS ( SELECT 1 FROM email_messages m WHERE m.thread_id = $1 AND NOT m.is_draft AND (NOT m.is_sent OR EXISTS ( SELECT 1 FROM email_message_recipients r JOIN email_contacts recipient ON recipient.id = r.contact_id JOIN email_contacts sender ON sender.id = m.from_contact_id WHERE r.message_id = m.id AND LOWER(recipient.email_address) = LOWER(sender.email_address) )) ) AS received) calc WHERE t.id = $1 AND t.has_received_mail IS DISTINCT FROM calc.received
